import sharp from 'sharp';
import type { CharacterType } from '../../../shared/types.js';

/**
 * Procedural placeholder art. These images are drawn from SVG shapes, NOT
 * generated by an AI model, and are always stored with isDemo = true and a
 * visible "PLACEHOLDER" label so they can't be mistaken for real generations.
 */

function hash(str: string): number {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

const esc = (s: string) =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

function wrap(text: string, max: number, lines: number): string[] {
  const words = text.split(/\s+/).filter(Boolean);
  const out: string[] = [];
  let cur = '';
  for (const w of words) {
    if ((cur + ' ' + w).trim().length > max) {
      out.push(cur.trim());
      cur = w;
      if (out.length === lines) break;
    } else cur += ' ' + w;
  }
  if (out.length < lines && cur.trim()) out.push(cur.trim());
  if (words.join(' ').length > out.join(' ').length && out.length) out[out.length - 1] += '…';
  return out;
}

export interface PlaceholderOptions {
  seedKey: string;
  characterType: CharacterType;
  width: number;
  height: number;
  title?: string;
  subtitle?: string;
  caption?: string;
  palette?: { skin?: string; hair?: string; outfit?: string; bgFrom?: string; bgTo?: string };
}

const SKINS = ['#c68863', '#b97a56', '#d29a74', '#a86b4a', '#e0ac84'];
const HAIRS = ['#1d1412', '#2b1a14', '#3a2418', '#121010'];
const OUTFITS = ['#7c3aed', '#2563eb', '#db2777', '#0d9488', '#ea580c', '#4f46e5'];
const BGS: [string, string][] = [
  ['#1e1b4b', '#4c1d95'],
  ['#0f172a', '#1d4ed8'],
  ['#312e81', '#7e22ce'],
  ['#172554', '#6d28d9'],
];

export function placeholderSvg(o: PlaceholderOptions): string {
  const h = hash(o.seedKey);
  const skin = o.palette?.skin ?? SKINS[h % SKINS.length];
  const hair = o.palette?.hair ?? HAIRS[(h >>> 3) % HAIRS.length];
  const outfit = o.palette?.outfit ?? OUTFITS[(h >>> 5) % OUTFITS.length];
  const [bgFrom, bgTo] = [o.palette?.bgFrom ?? BGS[(h >>> 7) % BGS.length][0], o.palette?.bgTo ?? BGS[(h >>> 7) % BGS.length][1]];
  const W = o.width;
  const H = o.height;
  const s = Math.min(W, H) / 1000; // scale factor relative to a 1000px square
  const cx = W / 2;
  const cy = H * 0.46;
  const cartoon = o.characterType === 'cartoon';
  const faceRx = (cartoon ? 175 : 150) * s;
  const faceRy = (cartoon ? 185 : 195) * s;
  const eyeR = (cartoon ? 30 : 13) * s;
  const eyeY = cy - 10 * s;
  const eyeDx = (cartoon ? 70 : 62) * s;
  const lines = o.caption ? wrap(o.caption, Math.floor(W / (20 * s)), 3) : [];
  const fontBase = 30 * s;

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">
  <defs>
    <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="${bgFrom}"/><stop offset="1" stop-color="${bgTo}"/>
    </linearGradient>
    <radialGradient id="glow" cx="0.5" cy="0.4" r="0.6">
      <stop offset="0" stop-color="#a78bfa" stop-opacity="0.35"/><stop offset="1" stop-color="#000" stop-opacity="0"/>
    </radialGradient>
    <linearGradient id="shade" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity="0.55"/>
    </linearGradient>
  </defs>
  <rect width="${W}" height="${H}" fill="url(#bg)"/>
  <rect width="${W}" height="${H}" fill="url(#glow)"/>
  <!-- hair back -->
  <ellipse cx="${cx}" cy="${cy + 60 * s}" rx="${faceRx * 1.35}" ry="${faceRy * 1.45}" fill="${hair}"/>
  <!-- shoulders / outfit -->
  <path d="M ${cx - 340 * s} ${H} Q ${cx - 330 * s} ${cy + 270 * s} ${cx} ${cy + 250 * s} Q ${cx + 330 * s} ${cy + 270 * s} ${cx + 340 * s} ${H} Z" fill="${outfit}"/>
  <rect x="${cx - 45 * s}" y="${cy + 150 * s}" width="${90 * s}" height="${110 * s}" rx="${30 * s}" fill="${skin}"/>
  <!-- face -->
  <ellipse cx="${cx}" cy="${cy}" rx="${faceRx}" ry="${faceRy}" fill="${skin}"/>
  <!-- fringe -->
  <path d="M ${cx - faceRx * 1.05} ${cy - 20 * s} Q ${cx - faceRx * 0.9} ${cy - faceRy * 1.25} ${cx + 10 * s} ${cy - faceRy * 1.05} Q ${cx + faceRx * 1.1} ${cy - faceRy * 1.1} ${cx + faceRx * 1.05} ${cy + 10 * s} Q ${cx + faceRx * 0.6} ${cy - faceRy * 0.75} ${cx - faceRx * 0.1} ${cy - faceRy * 0.72} Q ${cx - faceRx * 0.75} ${cy - faceRy * 0.6} ${cx - faceRx * 1.05} ${cy - 20 * s} Z" fill="${hair}"/>
  <!-- eyes -->
  ${[-1, 1]
    .map(
      (d) => `<ellipse cx="${cx + d * eyeDx}" cy="${eyeY}" rx="${eyeR * (cartoon ? 0.85 : 1.3)}" ry="${eyeR}" fill="${cartoon ? '#fff' : '#1b1110'}"/>
  ${cartoon ? `<circle cx="${cx + d * eyeDx}" cy="${eyeY + 4 * s}" r="${eyeR * 0.6}" fill="#2a1a12"/><circle cx="${cx + d * eyeDx + 7 * s}" cy="${eyeY - 6 * s}" r="${eyeR * 0.2}" fill="#fff"/>` : ''}
  <path d="M ${cx + d * eyeDx - 28 * s} ${eyeY - eyeR - 16 * s} Q ${cx + d * eyeDx} ${eyeY - eyeR - 28 * s} ${cx + d * eyeDx + 28 * s} ${eyeY - eyeR - 16 * s}" stroke="${hair}" stroke-width="${7 * s}" fill="none" stroke-linecap="round"/>`,
    )
    .join('\n')}
  <!-- cheeks + bindi -->
  <circle cx="${cx - 95 * s}" cy="${cy + 55 * s}" r="${24 * s}" fill="#f472b6" opacity="${cartoon ? 0.45 : 0.18}"/>
  <circle cx="${cx + 95 * s}" cy="${cy + 55 * s}" r="${24 * s}" fill="#f472b6" opacity="${cartoon ? 0.45 : 0.18}"/>
  <circle cx="${cx}" cy="${eyeY - 55 * s}" r="${6 * s}" fill="#be123c"/>
  <!-- nose + smile -->
  <path d="M ${cx} ${cy + 15 * s} Q ${cx - 10 * s} ${cy + 50 * s} ${cx + 4 * s} ${cy + 55 * s}" stroke="#7a4a32" stroke-width="${4 * s}" fill="none" opacity="0.6"/>
  <path d="M ${cx - 55 * s} ${cy + 90 * s} Q ${cx} ${cy + (cartoon ? 145 : 125) * s} ${cx + 55 * s} ${cy + 90 * s}" stroke="#9f1239" stroke-width="${8 * s}" fill="${cartoon ? '#fff' : 'none'}" stroke-linecap="round"/>
  <!-- earrings -->
  <circle cx="${cx - faceRx - 4 * s}" cy="${cy + 40 * s}" r="${10 * s}" fill="#fbbf24"/>
  <circle cx="${cx + faceRx + 4 * s}" cy="${cy + 40 * s}" r="${10 * s}" fill="#fbbf24"/>
  <rect y="${H * 0.62}" width="${W}" height="${H * 0.38}" fill="url(#shade)"/>
  ${o.title ? `<text x="${cx}" y="${H - (lines.length ? 150 : 95) * s - lines.length * fontBase * 1.2}" text-anchor="middle" font-family="Inter, DejaVu Sans, sans-serif" font-weight="700" font-size="${56 * s}" fill="#fff">${esc(o.title)}</text>` : ''}
  ${o.subtitle ? `<text x="${cx}" y="${H - (lines.length ? 100 : 50) * s - lines.length * fontBase * 1.2}" text-anchor="middle" font-family="Inter, DejaVu Sans, sans-serif" font-size="${28 * s}" fill="#c4b5fd">${esc(o.subtitle)}</text>` : ''}
  ${lines
    .map(
      (l, i) =>
        `<text x="${cx}" y="${H - 70 * s - (lines.length - 1 - i) * fontBase * 1.2}" text-anchor="middle" font-family="Inter, DejaVu Sans, sans-serif" font-size="${fontBase}" fill="#e5e7eb">${esc(l)}</text>`,
    )
    .join('\n')}
  <rect x="${cx - 125 * s}" y="${20 * s}" rx="${14 * s}" width="${250 * s}" height="${52 * s}" fill="#000" opacity="0.55"/>
  <text x="${cx}" y="${55 * s}" text-anchor="middle" font-family="Inter, DejaVu Sans, sans-serif" font-weight="700" font-size="${24 * s}" fill="#fbbf24" letter-spacing="${2 * s}">PLACEHOLDER</text>
</svg>`;
}

export async function placeholderPng(o: PlaceholderOptions): Promise<Buffer> {
  return sharp(Buffer.from(placeholderSvg(o))).png().toBuffer();
}
